// === Tab: mySketch ===
let grid, gridW = 25, gridH = 25,gridSX, gridSY;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(15);
	// // noLoop() removed for animation
	grid = new Grid(gridW, gridH);	
}

function draw() {
	background(64);

	grid.nSclX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width / 4;
	grid.nSclY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height / 4;

	const gridSX = width / gridW;
	const gridSY = height / gridH;
	grid.update();
	noFill();
	stroke(0)
	for (let y = 0; y < gridH; y++) {
		beginShape();
		curveVertex(0, (grid.getKumm(0, y) + y) * gridSY)
		for (let x = 0; x < gridW; x++) {
			const val = grid.getKumm(x, y);
			curveVertex(x * gridSX, (val + y) * gridSY)
			circle(x * gridSX, (val + y) * gridSY, 8)
		}
		curveVertex((gridW - 1) * gridSX, (grid.getKumm(gridW - 1, y) + y) * gridSY)
		endShape();
	}

	noStroke()
	fill(212)
	text("" + nf(grid.nSclX, 0, 2) + ", " + nf(grid.nSclY, 0, 2), 0, 10)
}

class Grid {
	constructor(w, h) {
		this.w = w;
		this.h = h;
		this.nOffX = random(2222);
		this.nOffY = random(2222);
		this.nSclX = random(0.02, 0.005);
		this.nSclY = random(0.5, 0.1);

		this.grid = [];
		for (let y = 0; y < gridH; y++) {
			this.grid[y] = [];
			for (let x = 0; x < gridW; x++) {
				this.grid[y][x] = 0;
			}
		}
		this.kumm = [];
		for (let y = 0; y < gridH; y++) {
			this.kumm[y] = [];
			for (let x = 0; x < gridW; x++) {
				this.kumm[y][x] = 0;
			}
		}		
		this.update();
	}

	update() {
		for (let y = 0; y < gridH; y++) {
			for (let x = 0; x < gridW; x++) {
				this.grid[y][x] = noise((this.nOffX + x) * this.nSclX, (this.nOffY + y) * this.nSclY); // , frameCount * (this.nSclX+this.nSclY));
				this.kumm[y][x] = this.grid[y][x]
				if (y > 0) this.kumm[y][x] += this.kumm[y-1][x];
			}
		}		
	}

	get(x, y) {
		return this.grid[y][x];
	}
	getKumm(x, y) {
		return this.kumm[y][x];
	}
}
